<script setup>
import{computed,onMounted,ref}from'vue';import{publicEvaluationApi as api}from'../../publicEvaluationApi'
const stats=ref({}),batches=ref([]),rows=ref([]),selected=ref(null),source=ref('HOTLINE_12345'),file=ref(null),message=ref(''),messageType=ref('success')
const negativeRate=computed(()=>stats.value.negative_rate||0)
function notice(text,type='success'){message.value=text;messageType.value=type}
async function load(){try{const [s,b,r]=await Promise.all([api.stats(),api.imports(),api.list({size:100})]);stats.value=s;batches.value=b;rows.value=r.items}catch(e){notice(e.message,'error')}}
async function upload(){if(!file.value){notice('请先选择需要归集的XLSX、CSV或JSON文件','error');return}try{selected.value=await api.importFile(source.value,file.value);notice(`归集完成：成功${selected.value.success_rows}，失败${selected.value.failed_rows}`);await load();selected.value=await api.batch(selected.value.id)}catch(e){notice(e.message,'error')}}
async function open(id){try{selected.value=await api.batch(id)}catch(e){notice(e.message,'error')}}
async function tag(x){const sentiment=prompt('情感标签：POSITIVE / NEUTRAL / NEGATIVE',x.sentiment);if(!sentiment)return;try{await api.sentiment(x.id,{sentiment});notice('情感标签已人工调整');await load()}catch(e){notice(e.message,'error')}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-info">本地XLSX、CSV或JSON模拟12345及政务平台归集；情感标签由确定性规则生成，不使用AI或NLP。</div><div v-if="message" class="alert" :class="messageType==='error'?'alert-danger':'alert-success'">{{message}}</div><div class="stat-grid"><div class="stat-card"><div class="num">{{stats.total||0}}</div><div class="label">有效评价</div></div><div class="stat-card"><div class="num">{{stats.org_count||0}}</div><div class="label">涉及机构</div></div><div class="stat-card"><div class="num">{{stats.avg_score||0}}</div><div class="label">平均分</div></div><div class="stat-card"><div class="num red">{{negativeRate}}%</div><div class="label">负向比例</div></div></div>
<div class="card"><div class="card-header"><h3>📥 本地外部评价归集</h3><span class="extra">最大10MB</span></div><div class="btn-group"><select v-model="source"><option value="HOTLINE_12345">12345热线</option><option value="GOV_SERVICE">政务服务好差评</option><option value="GOV_PLATFORM">政务平台留言</option></select><input type="file" accept=".xlsx,.csv,.json" @change="file=$event.target.files[0]"><button class="btn btn-primary" @click="upload">创建归集批次</button></div><table><thead><tr><th>批次</th><th>来源</th><th>文件</th><th>成功</th><th>失败</th><th>警告</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!batches.length"><td colspan="8">暂无批次</td></tr><tr v-for="x in batches" :key="x.id"><td>{{x.batch_code}}</td><td>{{x.source}}</td><td>{{x.original_file_name}}</td><td>{{x.success_rows}}</td><td>{{x.failed_rows}}</td><td>{{x.warning_rows}}</td><td>{{x.status}}</td><td><button class="btn btn-sm btn-outline" @click="open(x.id)">校验明细</button></td></tr></tbody></table></div>
<div class="card"><div class="card-header"><h3>📊 归集结果与规则情感</h3></div><table><thead><tr><th>机构</th><th>来源</th><th>服务事项</th><th>评分</th><th>评价内容</th><th>情感</th><th>操作</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="7">暂无数据</td></tr><tr v-for="x in rows" :key="x.id"><td>{{x.unit_name}}</td><td>{{x.source}}</td><td>{{x.service_item_name}}</td><td>{{x.overall_score}}</td><td>{{x.comment_text||'-'}}</td><td><span class="tag" :class="x.sentiment==='NEGATIVE'?'tag-danger':'tag-info'">{{x.sentiment}} / {{x.sentiment_source}}</span></td><td><button class="btn btn-sm btn-outline" @click="tag(x)">人工调整</button></td></tr></tbody></table></div>
<div v-if="selected" class="modal-overlay" @click.self="selected=null"><div class="modal"><h3>归集校验报告</h3><div class="alert alert-info">成功 {{selected.success_rows}} / 失败 {{selected.failed_rows}} / 警告 {{selected.warning_rows}}</div><table><thead><tr><th>行</th><th>机构编码</th><th>错误</th></tr></thead><tbody><tr v-if="!selected.errors?.length"><td colspan="3">无失败记录</td></tr><tr v-for="x in selected.errors" :key="x.id"><td>{{x.source_row_number}}</td><td>{{x.org_code}}</td><td>{{x.error_message}}</td></tr></tbody></table><button class="btn btn-outline" @click="selected=null">关闭</button></div></div>
</section></template>
<style scoped>.modal-overlay{position:fixed;inset:0;background:#0006;z-index:1000;display:flex;align-items:center;justify-content:center}.modal{background:#fff;padding:22px;border-radius:12px;width:min(850px,94vw);max-height:88vh;overflow:auto}</style>
